{
  "name": "concept-loom",
  "version": "1.1.0",
  "description": "A portable, connection-first learning companion for Codex, Claude Code, OpenCode, and DeepSeek Harness.",
  "type": "module",
  "private": true,
  "bin": {
    "concept-loom": "src/bridge.mjs"
  },
  "scripts": {
    "start": "node src/bridge.mjs",
    "test": "node --test",
    "check": "node --check src/bridge.mjs && node --check src/checkpoints.mjs && node --check src/notebook.mjs && node --check src/diagrams.mjs && node --check src/progress.mjs && node --check scripts/setup.mjs",
    "verify": "npm run check && npm test"
  },
  "engines": {
    "node": ">=20"
  },
  "license": "MIT"
}
